1.3 Interactive app: what censoring does
Each line is a patient. Patients join the study at different times during the recruitment period, and the study stops at a fixed calendar date. A filled dot ● is an observed event. A cross ✕ is a censored observation. Tick Show what we never see to reveal the true event times hidden by censoring.

import {makeRandom, mean, quiz} from "./js/survtools.js"








viewof c1Scen = Inputs.radio(["Default", "Short study (2 years)", "No drop-out, 10-year study"], {value: "Default", label: "Scenario"})
c1P = ({"Default": {}, "Short study (2 years)": {"study": 2}, "No drop-out, 10-year study": {"drop": 0, "study": 10}})[c1Scen]
viewof c1 = Inputs.form({
  n:       Inputs.range([5, 40],  {value: c1P.n ?? 20,  step: 1,   label: "Patients shown"}),
  accrual: Inputs.range([0, 4],   {value: c1P.accrual ?? 2,   step: 0.5, label: "Recruitment period (yrs)"}),
  study:   Inputs.range([1, 10],  {value: c1P.study ?? 5,   step: 0.5, label: "Study length (yrs)"}),
  median:  Inputs.range([0.5, 8], {value: c1P.median ?? 3,   step: 0.5, label: "True median survival (yrs)"}),
  drop:    Inputs.range([0, 0.5], {value: c1P.drop ?? 0.1, step: 0.05, label: "Drop-out rate (per yr)"}),
  seed:    Inputs.range([1, 100], {value: c1P.seed ?? 7,   step: 1,   label: "Random seed"})
}, {template: formGrid})
formGrid = inputs =&gt; html`&lt;div class="form-grid"&gt;${Object.values(inputs)}&lt;/div&gt;`
viewof c1view = Inputs.radio(["Calendar time", "Time since entry"], {value: "Calendar time", label: "Time axis"})
viewof c1truth = Inputs.toggle({label: "Show what we never see", value: false})












































function simCensoring(p, n, seed) {
  const r = makeRandom(seed);
  const rate = Math.LN2 / p.median;
  const studyEnd = Math.max(p.study, p.accrual);
  return Array.from({length: n}, (_, i) =&gt; {
    const entry = r.unif() * p.accrual;
    const tEvent = r.exp(rate);
    const tDrop = p.drop &gt; 0 ? r.exp(p.drop) : Infinity;
    const tAdmin = studyEnd - entry;
    const time = Math.min(tEvent, tDrop, tAdmin);
    const status = tEvent &lt;= Math.min(tDrop, tAdmin) ? 1 : 0;
    const reason = status ? "Event" : (tDrop &lt; tAdmin ? "Censored: dropped out" : "Censored: study ended");
    return {id: i + 1, entry, tEvent, time, status, reason};
  });
}
c1data = simCensoring(c1, c1.n, c1.seed)
c1big  = simCensoring(c1, 5000, c1.seed + 1000)























{
  const cal = c1view === "Calendar time";
  const studyEnd = Math.max(c1.study, c1.accrual);
  const d = c1data.map(p =&gt; ({...p,
    x0: cal ? p.entry : 0,
    x1: cal ? p.entry + p.time : p.time,
    xt: cal ? p.entry + p.tEvent : p.tEvent}));
  const hidden = d.filter(p =&gt; !p.status);
  return Plot.plot({
    height: 120 + 14 * c1.n, marginLeft: 50,
    x: {label: cal ? "Calendar time since study opened (years) →" : "Time since patient entered (years) →",
        domain: [0, Math.max(studyEnd, ...(c1truth ? d.map(p =&gt; Math.min(p.xt, studyEnd * 2)) : [studyEnd]))]},
    y: {label: "Patient", tickFormat: d =&gt; d, domain: d.map(p =&gt; p.id)},
    color: {legend: true, domain: ["Event", "Censored: study ended", "Censored: dropped out"],
            range: ["#D55E00", "#0072B2", "#CC79A7"]},
    marks: [
      cal ? Plot.ruleX([studyEnd], {stroke: "#888", strokeDasharray: "4,3"}) : null,
      cal && c1.accrual &gt; 0 ? Plot.rectX([{x1: 0, x2: c1.accrual}], {x1: "x1", x2: "x2", fill: "#999", fillOpacity: 0.08}) : null,
      c1truth ? Plot.ruleY(hidden, {y: "id", x1: "x1", x2: p =&gt; Math.min(p.xt, studyEnd * 2), stroke: "#aaa", strokeDasharray: "2,3"}) : null,
      c1truth ? Plot.dot(hidden, {y: "id", x: p =&gt; Math.min(p.xt, studyEnd * 2), stroke: "#aaa", r: 3.5}) : null,
      Plot.ruleY(d, {y: "id", x1: "x0", x2: "x1", stroke: "reason", strokeWidth: 2.5}),
      Plot.dot(d.filter(p =&gt; p.status), {y: "id", x: "x1", fill: "reason", r: 4.5}),
      Plot.dot(d.filter(p =&gt; !p.status), {y: "id", x: "x1", stroke: "reason", symbol: "times", r: 5, strokeWidth: 2})
    ]
  });
}







{
  const big = c1big;
  const trueMean = c1.median / Math.LN2;
  const rows = [
    {Quantity: "True mean survival time", Value: trueMean, Comment: "What we want to know"},
    {Quantity: "Mean of observed times (ignoring censoring)", Value: mean(big.map(d =&gt; d.time)), Comment: "Too low: censored times are cut short"},
    {Quantity: "Mean time among those with an event", Value: mean(big.filter(d =&gt; d.status).map(d =&gt; d.time)) || NaN, Comment: "Too low: long survivors are left out"},
    {Quantity: "Proportion censored", Value: mean(big.map(d =&gt; 1 - d.status)), Comment: "With these settings, over 5,000 simulated patients"}
  ];
  return Inputs.table(rows, {format: {Value: v =&gt; isNaN(v) ? "–" : v.toFixed(2)}, layout: "auto", rows: 5});
}













TipThings to try



For each one, predict first: decide what you expect to see, then pick the scenario and check. Committing to a prediction, even a wrong one, makes the result stick.

Predict: if every patient’s line started at 0, which patients would have the shortest lines? Then switch the time axis to Time since entry. This is how survival software sees the data.
Predict: if the study lasts only 2 years, will the two naive averages move closer to the truth or further away? Then pick Short study (2 years).
Predict: what happens to the naive averages when almost no one is censored? Then pick No drop-out, 10-year study.









NoteAnswers: what you should see






Time since entry. Every line now starts at 0. Patients who joined near the end of the recruitment period have the shortest lines ending in a blue ✕. They were censored early because the study closed, not because of anything about their health. That’s why administrative censoring is usually non-informative.
Study length 2 years. Most lines now end in a ✕. With the other settings at their defaults, about 80% of patients are censored. The naive mean falls to about 0.8 years (truth: 4.3), and the mean among those with an event to about 0.6 years. Both get worse the shorter the follow-up. The Kaplan–Meier method (Chapter 2) uses the censored patients properly.
No drop-out, 10-year study. Only people still alive after 8–10 years are censored, about 13% of patients. The naive mean rises to about 3.8 years, much closer to 4.3. It’s still too low, because the few censored patients are the longest survivors. Censoring causes the bias: the less of it there is, the smaller the bias.

2.5 Interactive app: two-arm study simulator
Here we simulate a two-arm study where we know the truth. The dashed lines are the true survival curves. The solid lines are the KM estimates from one simulated sample. Change the sample size and seed to see how much KM curves and log-rank p-values vary from sample to sample.


viewof k2Scen = Inputs.radio(["Default", "Small study (20 per arm)", "Large study (150 per arm)", "No true effect (HR = 1)", "Short follow-up (6 months)", "Heavy drop-out"], {value: "Default", label: "Scenario"})
k2P = ({"Default": {}, "Small study (20 per arm)": {"n": 20}, "Large study (150 per arm)": {"n": 150}, "No true effect (HR = 1)": {"hr": 1}, "Short follow-up (6 months)": {"fu": 6}, "Heavy drop-out": {"drop": 0.08}})[k2Scen]
viewof k2 = Inputs.form({
  n:      Inputs.range([10, 500], {value: k2P.n ?? 60, step: 10, label: "Patients per arm"}),
  median: Inputs.range([3, 36], {value: k2P.median ?? 12, step: 1, label: "Control median (months)"}),
  hr:     Inputs.range([0.3, 1.5], {value: k2P.hr ?? 0.6, step: 0.05, label: "True hazard ratio (B vs A)"}),
  fu:     Inputs.range([6, 60], {value: k2P.fu ?? 30, step: 6, label: "Max follow-up (months)"}),
  drop:   Inputs.range([0, 0.1], {value: k2P.drop ?? 0.01, step: 0.005, label: "Drop-out rate (per month)"}),
  seed:   Inputs.range([1, 200], {value: k2P.seed ?? 1, step: 1, label: "Random seed (new study)"}),
  ci:     Inputs.toggle({label: "Show 95% CIs", value: k2P.ci ?? true})
}, {template: formGrid})
formGrid = inputs =&gt; html`&lt;div class="form-grid"&gt;${Object.values(inputs)}&lt;/div&gt;`






























k2sim = {
  const r = makeRandom(k2.seed);
  const lam0 = Math.LN2 / k2.median;
  const out = [];
  for (const [g, lam] of [["A (control)", lam0], ["B (treatment)", lam0 * k2.hr]]) {
    for (let i = 0; i &lt; k2.n; i++) {
      const tE = r.exp(lam);
      const tC = Math.min(k2.fu * (0.5 + 0.5 * r.unif()), k2.drop &gt; 0 ? r.exp(k2.drop) : Infinity);
      out.push({group: g, g: g.startsWith("B") ? 1 : 0, time: Math.min(tE, tC), event: tE &lt;= tC ? 1 : 0});
    }
  }
  return out;
}
k2fits = ["A (control)", "B (treatment)"].flatMap(g =&gt; {
  const d = k2sim.filter(x =&gt; x.group === g);
  return kmFit(d.map(x =&gt; x.time), d.map(x =&gt; x.event)).map(r =&gt; ({...r, group: g}));
})
k2true = {
  const lam0 = Math.LN2 / k2.median, pts = [];
  for (let t = 0; t &lt;= k2.fu; t += k2.fu / 100) {
    pts.push({time: t, surv: Math.exp(-lam0 * t), group: "A (control)"});
    pts.push({time: t, surv: Math.exp(-lam0 * k2.hr * t), group: "B (treatment)"});
  }
  return pts;
}
k2lr = logrank(k2sim.map(d =&gt; d.time), k2sim.map(d =&gt; d.event), k2sim.map(d =&gt; d.g))






























Plot.plot({
  height: 340, y: {domain: [0, 1], grid: true, label: "Survival probability"},
  x: {label: "Months →", domain: [0, k2.fu]},
  color: {legend: true, domain: ["A (control)", "B (treatment)"], range: ["#E69F00", "#0072B2"]},
  marks: [
    k2.ci ? Plot.areaY(k2fits, {x: "time", y1: "lower", y2: "upper", fill: "group", fillOpacity: 0.15, curve: "step-after"}) : null,
    Plot.line(k2true, {x: "time", y: "surv", stroke: "group", strokeDasharray: "5,4", strokeOpacity: 0.8}),
    Plot.line(k2fits, {x: "time", y: "surv", stroke: "group", strokeWidth: 2.2, curve: "step-after"}),
    Plot.dot(k2fits.filter(r =&gt; r.ncens &gt; 0), {x: "time", y: "surv", stroke: "group", symbol: "plus", r: 3})
  ]
})







{
  const tbl = [];
  for (const g of ["A (control)", "B (treatment)"]) {
    const d = k2sim.filter(x =&gt; x.group === g);
    const f = k2fits.filter(r =&gt; r.group === g);
    const isA = g.startsWith("A");
    tbl.push({Arm: g, N: d.length, Events: d.filter(x =&gt; x.event).length,
      "Observed (O)": isA ? k2lr.O0 : k2lr.O1, "Expected (E)": (isA ? k2lr.E0 : k2lr.E1).toFixed(1),
      "KM median": isNaN(kmMedian(f)) ? "not reached" : kmMedian(f).toFixed(1),
      "True median": (k2.median / (isA ? 1 : k2.hr)).toFixed(1)});
  }
  return Inputs.table(tbl, {layout: "auto"});
}







html`&lt;p style="font-size:1.05em"&gt;Log-rank test: χ² = &lt;b&gt;${k2lr.chisq.toFixed(2)}&lt;/b&gt; on 1 df,
p = &lt;b style="color:${k2lr.p &lt; 0.05 ? '#0072B2' : '#D55E00'}"&gt;${k2lr.p &lt; 0.0001 ? "&lt; 0.0001" : k2lr.p.toFixed(4)}&lt;/b&gt;
${k2lr.p &lt; 0.05 ? "(significant at 5%)" : "(not significant at 5%)"}&lt;/p&gt;`













TipThings to try



For each one, predict first: decide what you expect to see, then pick the scenario and check. Committing to a prediction, even a wrong one, makes the result stick.

Power. Predict: with only 20 patients per arm and a real effect (HR = 0.6), how often will the log-rank test give p &lt; 0.05? Then pick Small study (20 per arm) and step through several seeds. Compare with Large study (150 per arm).
No effect. Predict: if the treatment does nothing, can the test still give p &lt; 0.05? Then pick No true effect (HR = 1) and step through seeds.
Censoring. Predict: if follow-up stops at 6 months, what happens to the medians and the p-value? Then pick Short follow-up (6 months).
The tail. Predict: with many drop-outs, which part of the curves will be most uncertain? Then pick Heavy drop-out.









NoteAnswers: what you should see






Power. With 20 per arm, the true HR of 0.6 gives p &lt; 0.05 in only about 1 seed in 5. The chance that a study detects a real effect (p &lt; 0.05) is called its power. Across 200 simulated studies, the power here was about 20%. A real effect is often missed in a small study. With 150 per arm, power is about 90%. Notice also how much the 20-per-arm KM curves wander around the dashed true curves.
No effect. With HR = 1, about 5% of seeds give p &lt; 0.05. That’s exactly what a 5% significance level means: these are false positives. If you click through 20 seeds you’ll probably find one or two.
Short follow-up. With 6 months of follow-up, both medians are “not reached” (the control median is 12 months), there are only a handful of events, and power falls from about 55% to about 22% (at 60 per arm). The number of patients hasn’t changed, only the number of events.
High drop-out. The risk table thins out quickly, so the confidence bands balloon at the right of the plot. On average the curves still follow the dashed truth, because random drop-out is non-informative. KM handles it correctly, but you get less precision.

2.7 Reporting Kaplan–Meier results
A good KM summary normally includes:

the plot, with a risk table and censoring marks;
the number of events and number at risk in each group;
median survival with a 95% CI (or “not reached”);
survival at clinically meaningful times (e.g. 1-year survival) with CIs;
the log-rank p-value, and an effect size such as a hazard ratio from a Cox model (Chapter 3).


2.7.1 Writing it up
A sentence template you can adapt:

Median survival was [X] days (95% CI [a] to [b]) in [group 1] and [Y] days (95% CI [c] to [d]) in [group 2]. At [time], [p1]% (95% CI …) of [group 1] and [p2]% (95% CI …) of [group 2] were still alive. Survival differed between the groups (log-rank test, \(\chi^2\) = [value], [df] df, p = [value]).

Filled in for the lung data:

Median survival was 426 days (95% CI 348 to 550) in women and 270 days (95% CI 212 to 310) in men. At one year, 53% (95% CI 42% to 66%) of women and 34% (95% CI 26% to 43%) of men were still alive. Survival differed between the sexes (log-rank test, \(\chi^2\) = 10.3, 1 df, p = 0.001).

The gtsummary package’s tbl_survfit() can produce these numbers as a table.

3.2 Interactive app: proportional hazards explorer
The left-hand plots show the true hazards and survival curves for two groups. The baseline hazard comes from a Weibull distribution:

shape &lt; 1: hazard falls over time (e.g. risk after surgery);
shape = 1: constant hazard;
shape &gt; 1: hazard rises over time (e.g. ageing).

Tick Allow non-proportional hazards to give the treatment a different HR before and after a change-point. Then compare how a single Cox HR, fitted to a simulated sample, summarises the effect.

import {kmFit, coxFit, makeRandom, quiz} from "./js/survtools.js"








viewof phScen = Inputs.radio(["Default", "Falling hazard (shape 0.5)", "Rising hazard (shape 2.5)", "Benefit that reverses (non-PH)"], {value: "Default", label: "Scenario"})
phP = ({"Default": {}, "Falling hazard (shape 0.5)": {"shape": 0.5}, "Rising hazard (shape 2.5)": {"shape": 2.5}, "Benefit that reverses (non-PH)": {"nonph": true}})[phScen]
viewof ph = Inputs.form({
  shape:  Inputs.range([0.4, 3], {value: phP.shape ?? 1.0, step: 0.1, label: "Baseline hazard shape (Weibull)"}),
  scale:  Inputs.range([1, 10],  {value: phP.scale ?? 4,   step: 0.5, label: "Baseline scale (years)"}),
  hr1:    Inputs.range([0.2, 3], {value: phP.hr1 ?? 0.5, step: 0.05, label: "HR (treated vs control)"}),
  nonph:  Inputs.toggle({label: "Allow non-proportional hazards", value: phP.nonph ?? false}),
  hr2:    Inputs.range([0.2, 3], {value: phP.hr2 ?? 1.5, step: 0.05, label: "…HR after change-point"}),
  tc:     Inputs.range([0.5, 8], {value: phP.tc ?? 2,   step: 0.5, label: "…change-point (years)"}),
  n:      Inputs.range([50, 2000], {value: phP.n ?? 400, step: 50, label: "Simulated n per group"}),
  seed:   Inputs.range([1, 100], {value: phP.seed ?? 3, step: 1, label: "Random seed"})
}, {template: formGrid})
formGrid = inputs =&gt; html`&lt;div class="form-grid"&gt;${Object.values(inputs)}&lt;/div&gt;`






























phTmax = ph.scale * 2.5
// cumulative baseline hazard and treated cumulative hazard (piecewise HR)
H0 = t =&gt; Math.pow(t / ph.scale, ph.shape)
h0 = t =&gt; (ph.shape / ph.scale) * Math.pow(Math.max(t, 1e-6) / ph.scale, ph.shape - 1)
hrAt = t =&gt; (!ph.nonph || t &lt; ph.tc) ? ph.hr1 : ph.hr2
H1 = t =&gt; (!ph.nonph || t &lt; ph.tc) ? ph.hr1 * H0(t) : ph.hr1 * H0(ph.tc) + ph.hr2 * (H0(t) - H0(ph.tc))
phCurves = {
  const pts = [];
  for (let i = 1; i &lt;= 200; i++) {
    const t = phTmax * i / 200;
    pts.push({t, group: "Control", h: h0(t), S: Math.exp(-H0(t)), cll: Math.log(H0(t))});
    pts.push({t, group: "Treated", h: h0(t) * hrAt(t), S: Math.exp(-H1(t)), cll: Math.log(H1(t))});
  }
  return pts;
}












































phColor = ({legend: true, domain: ["Control", "Treated"], range: ["#E69F00", "#0072B2"]})
html`&lt;div class="app-grid"&gt;
${Plot.plot({title: "Hazard h(t)", height: 230, width: 310, color: phColor,
  y: {label: "Hazard", domain: [0, Math.min(d3.max(phCurves, d =&gt; d.h), 5 * d3.median(phCurves, d =&gt; d.h) + 0.1)], grid: true},
  x: {label: "Years"},
  marks: [Plot.line(phCurves, {x: "t", y: "h", stroke: "group", strokeWidth: 2, clip: true})]})}
${Plot.plot({title: "Survival S(t)", height: 230, width: 310, color: phColor,
  y: {domain: [0, 1], grid: true, label: "Survival"}, x: {label: "Years"},
  marks: [Plot.line(phCurves, {x: "t", y: "S", stroke: "group", strokeWidth: 2})]})}
${Plot.plot({title: "log(−log S(t)) vs log time: parallel lines = PH", height: 230, width: 310, color: phColor,
  y: {label: "log(−log S)", grid: true}, x: {label: "Years (log scale)", type: "log", tickFormat: d =&gt; d},
  marks: [Plot.line(phCurves.filter(d =&gt; isFinite(d.cll)), {x: "t", y: "cll", stroke: "group", strokeWidth: 2})]})}
${Plot.plot({title: "Hazard ratio over time", height: 230, width: 310,
  y: {label: "HR (log scale)", type: "log", domain: [0.15, 4], grid: true, ticks: [0.2, 0.3, 0.5, 1, 2, 3, 4], tickFormat: d =&gt; d}, x: {label: "Years"},
  marks: [Plot.ruleY([1], {stroke: "#888"}),
          Plot.line(phCurves.filter(d =&gt; d.group === "Treated"), {x: "t", y: d =&gt; hrAt(d.t), stroke: "black", strokeWidth: 2}),
          Plot.ruleY([phFit.hr], {stroke: "#0072B2", strokeDasharray: "5,4", strokeWidth: 2}),
          Plot.text([phFit.hr], {y: d =&gt; d, x: phTmax, text: d =&gt; `Cox HR = ${d.toFixed(2)}`, textAnchor: "end", dy: -7, fill: "#0072B2"})]})}
&lt;/div&gt;`
















phSim = {
  const r = makeRandom(ph.seed);
  const out = [];
  const admin = phTmax * 0.8;
  for (const g of [0, 1]) for (let i = 0; i &lt; ph.n; i++) {
    const E = r.exp(1);  // unit exponential; invert cumulative hazard
    let t;
    if (g === 0) t = ph.scale * Math.pow(E, 1 / ph.shape);
    else if (!ph.nonph || E &lt; ph.hr1 * H0(ph.tc)) t = ph.scale * Math.pow(E / ph.hr1, 1 / ph.shape);
    else t = ph.scale * Math.pow(H0(ph.tc) + (E - ph.hr1 * H0(ph.tc)) / ph.hr2, 1 / ph.shape);
    const c = admin * r.unif() + admin * 0.25;
    out.push({g, time: Math.min(t, c), event: t &lt;= c ? 1 : 0});
  }
  return out;
}
phFit = coxFit(phSim.map(d =&gt; d.time), phSim.map(d =&gt; d.event), phSim.map(d =&gt; [d.g]))[0]
phKM = [0, 1].flatMap(g =&gt; {
  const d = phSim.filter(x =&gt; x.g === g);
  return kmFit(d.map(x =&gt; x.time), d.map(x =&gt; x.event)).map(r =&gt; ({...r, group: g ? "Treated" : "Control"}));
})























html`&lt;div class="app-grid"&gt;
${Plot.plot({title: `Kaplan–Meier curves from one simulated study (n = ${2 * ph.n})`, height: 250, width: 310, color: phColor,
  y: {domain: [0, 1], grid: true, label: "Survival"}, x: {label: "Years"},
  marks: [Plot.line(phKM, {x: "time", y: "surv", stroke: "group", curve: "step-after", strokeWidth: 2})]})}
&lt;div class="app-result"&gt;
&lt;h4&gt;Cox model fitted to the simulated data&lt;/h4&gt;
&lt;p&gt;Estimated HR = &lt;b&gt;${phFit.hr.toFixed(2)}&lt;/b&gt; (95% CI ${phFit.lower.toFixed(2)} to ${phFit.upper.toFixed(2)})&lt;/p&gt;
&lt;p&gt;True HR: &lt;b&gt;${ph.nonph ? `${ph.hr1} before year ${ph.tc}, ${ph.hr2} after` : ph.hr1}&lt;/b&gt;&lt;/p&gt;
&lt;p style="color:#555"&gt;${ph.nonph
  ? "With non-proportional hazards, the single Cox HR is a weighted average of the early and late HRs. The weights depend on when the events happen, which depends on follow-up and censoring. It may describe neither period well."
  : "When hazards are proportional, the Cox HR estimates the true HR without our needing to know anything about the baseline hazard's shape. Try changing the shape: the estimate barely moves."}&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;`













TipThings to try



For each one, predict first: decide what you expect to see, then pick the scenario and check. Committing to a prediction, even a wrong one, makes the result stick.

Baseline shape. Predict: if the hazard falls steeply over time, or rises steeply, will the estimated HR change? Then pick Falling hazard (shape 0.5) and Rising hazard (shape 2.5), and compare the Cox estimate with the Default.
The log(−log) plot. On the Default scenario, look at the third plot. Predict: what will happen to these two lines when hazards are not proportional? Keep your answer for item 3.
Non-proportional hazards. Predict: if treatment halves the hazard for 2 years and then raises it by 50%, what will the KM curves look like, and what single HR will the Cox model report? Then pick Benefit that reverses (non-PH).









NoteAnswers: what you should see






Baseline shape. At shape 0.5 the hazard plunges early, and at 2.5 it climbs steeply. In both cases the treated hazard is always half the control hazard, so the HR line stays flat at 0.5. With the default seed the Cox estimates are 0.47, 0.45 and 0.48 for shapes 0.5, 1 and 2.5. These all differ from 0.5 only by sampling error. The model never needed to know the shape of \(h_0(t)\).
log(−log) plot. The lines are parallel, and the vertical gap between them is \(\log(\text{HR}) = \log(0.5) \approx -0.69\). In real data you would plot plot(survfit(...), fun = "cloglog"). Lines that converge, diverge or cross suggest the PH assumption doesn’t hold.
Non-PH (0.5 then 1.5). The KM curves separate early, then the gap closes as the treated group’s hazard overtakes the control group’s. The log(−log) lines are no longer parallel, and the HR plot steps up at year 2. With the default seed, the single Cox HR is about 0.86, which suggests a small benefit and describes neither period. In practice, cox.zph() would flag this. You would then report period-specific HRs (split time at year 2) or use the restricted mean survival time instead.

with informative censoring, the patients who leave the risk set are different from those who stay;
with competing risks, patients who can no longer have the event are treated as if they still could;
with immortal time bias, patients are counted in a group before they have actually joined it.

4.1 Trap 1: informative censoring
Chapter 1 introduced the key assumption behind Kaplan–Meier curves, the log-rank test and the Cox model: censoring must be non-informative. A patient who is censored must have the same future risk as the patients who are still being followed.
It’s called informative censoring when that fails, because then the fact that someone was censored tells you something about their risk. Suppose the sickest patients stop coming to clinic because they’re too ill to travel. When one of them is censored, that tells you they were probably about to die. Kaplan–Meier can’t know this. It assumes each censored patient would have done as well as the patients who stayed, so it quietly replaces sick patients with healthier ones.

